import json,pathlib
b=pathlib.Path('data/rcap-all50/overlays/census-v1/az/az-record-sealing-dismissal-not-guilty-set--official-pdf-fill')
e=pathlib.Path('data/rcap-grade-a/packet-factory-24h/vf69/az-dismissal-final-evidence-20260911')
m=json.loads((b/'production-field-map.json').read_text())
rows=[]
def add(role,fields,page,label,condition,category):
 mp=next(x for x in m['maps'] if x['documentRole']==role)
 for field in fields:
  r=next(x for x in mp['canonicalRefusals'] if x['fieldName']==field)
  assert r['requiredBeforeFiling'] is True and r['conditionalRequirement'] is None
  assert all(w['page']==page for w in r['sourceFieldInfo']['sourceWidgets'])
  rows.append({'documentRole':role,'fieldId':field,'documentId':mp['documentId'],'sourcePage':page,'sourceLabel':label,'currentDisposition':r['completenessDisposition'],'currentRequiredBeforeFiling':r['requiredBeforeFiling'],'currentConditionalRequirement':r['conditionalRequirement'],'applicableCondition':condition,'defectCategory':category,'sourceWidgets':r['sourceFieldInfo']['sourceWidgets'],'participantInstructionsAlsoDemandsField':f'participant required field {field}' in (b/'participant-instructions.md').read_text()})
add('petition',['Plaintiff'],1,'OR if no charges were filed: In Re the Matter of: Name (FIRST, MI, LAST)','Only no-charge In Re caption; inapplicable on charged dismissal/not-guilty route, which correctly fills Defendant.','OFF_ROUTE')
add('petition',['Check Box2'],1,'Amended (corrected) petition; Select if you are amending an existing petition.','Select only when amending an existing petition.','CONDITIONAL_ELECTION')
add('petition',['Check Box3'],2,'Arrest records of an arrest occurring on or about ... by the following law enforcement agency','Participant selects only when requesting this record scope; source says check only those that apply.','CONDITIONAL_ELECTION')
add('petition',['ArrestOccured','Agency'],2,'Arrest records of an arrest occurring on or about ... by the following law enforcement agency','Supply arrest date/agency for the arrest-record scope if requested; do not require an unselected scope.','CONDITIONAL_SCOPE_DETAIL')
add('petition',['Check Box4'],2,'Charging documents created by the following prosecuting agency (Do not check this box if no charges were filed)','Participant selects if requesting charging-document scope; available to this charged route but not compulsory.','CONDITIONAL_ELECTION')
add('petition',['ProAgency'],2,'Charging documents created by the following prosecuting agency','Supply prosecutor identity for the charging-document scope if requested.','CONDITIONAL_SCOPE_DETAIL')
add('petition',['Check Box5'],2,'All records relating to the eligible charge(s) in court case number','Participant selects only if requesting this scope; no rule requires every scope checkbox to be marked.','CONDITIONAL_ELECTION')
add('petition',['CourtCase'],2,'All records relating to the eligible charge(s) in court case number','Supply case number for that record scope if selected; the separate charged-case Case/CourtCaseNum requirements remain.','CONDITIONAL_SCOPE_DETAIL')
add('petition',['CourtAdj2'],2,'Court that adjudicated the charge(s) ... [second continuation line]','Use only if the court identity exceeds the filled CourtAdj1 line; both fixture court names fit entirely on CourtAdj1.','OPTIONAL_CONTINUATION')
add('petition',['Count1','Count2','Count3','Count4'],2,'Court case number if charge(s) were filed: Count I; Count II; Count III; Count IV','Complete only actual charge/count rows established from the record; do not require four counts to exist.','CONDITIONAL_REPEATING_ROW')
add('petition',['Check Box6'],2,'Additional counts continue on a separate page.','Select only when actual additional counts require continuation beyond the provided four count rows.','CONDITIONAL_ELECTION')
add('petition',['ArrestLoc'],3,'3. ADDITIONAL CASE RECORD INFORMATION (if known); a. Location of arrest','Supply only if known.','SOURCE_OPTIONAL')
add('petition',['AgencyName'],3,'3. ADDITIONAL CASE RECORD INFORMATION (if known); b. Name of the arresting agency','Supply only if known.','SOURCE_OPTIONAL')
add('petition',['AgencyDate'],3,'3. ADDITIONAL CASE RECORD INFORMATION (if known); c. Date of arrest','Supply only if known.','SOURCE_OPTIONAL')
add('petition',['ProsAgency1'],3,'3. ADDITIONAL CASE RECORD INFORMATION (if known); d. Name of the prosecuting agency if charges were filed','Supply only if known and charges were filed; charges were filed on this route.','SOURCE_OPTIONAL')
add('petition',['ProsAgency2'],3,'3(d). Name of the prosecuting agency if charges were filed [continuation line]','Use if the optional known prosecutor name needs a second line.','OPTIONAL_CONTINUATION')
add('petition',['JusticeCourt1'],3,'3(e). Name of the justice court and the justice court case number if the case was initially filed in a justice court but was transferred to the superior court.','Supply if known and justice-to-superior transfer occurred; canonical direct-charging route does not meet that condition. One field has two source widgets.','CONDITIONAL_SOURCE_OPTIONAL')
add('petition',['EnteredOn1'],3,'I was charged with a criminal offense and a judgment of guilty was entered on','Only for the guilty-judgment situation; inapplicable to this dismissal/not-guilty route. Preserve EnteredOn as the dismissal/not-guilty disposition date.','OFF_ROUTE')
add('petition',['PetDate'],4,'If yes, what was the date of your last petition?','Only if the participant previously filed a sealing petition in this case (Section III.1 = Yes).','CONDITIONAL_HISTORY_DETAIL')
add('petition',['Discharge'],4,'If yes, what was the date you completed the non-monetary conditions of probation or sentence and were discharged by the court?','Only if records were sealed in a previous case (Section III.2 = Yes).','CONDITIONAL_HISTORY_DETAIL')
add('petition',['Check Box16'],4,'If you are filing this petition to have a conviction sealed, have you been convicted of any other offense since the conviction ...? Yes / No / N/A','Question is conditioned on sealing a conviction. This family seals dismissal/not-guilty records; preserve the source N/A choice and do not demand conviction-history facts.','CONDITIONAL_ELECTION')
add('petition',['Jurisdiction','ChargesFiled','DateofCharge'],4,'If you have additional pending charges, please provide: Jurisdiction; Charges filed; Date of the charges','Only if additional pending charges exist; preserve the separate pending-charge yes/no/unknown response and self-help stop.','CONDITIONAL_PENDING_DETAIL')
add('petition',['Consider1','Consider2','Consider3'],4,'Is there anything else you would like the court to consider regarding this petition?','Optional further information; use only needed lines. Do not demand three populated lines. Registry best-interests question remains a distinct requirement, not three mandatory continuation fields.','SOURCE_OPTIONAL')
add('petition',['Check Box19'],4,'Attached is other pertinent documentation (non-originals). List attached documents:','Select only when other pertinent documents are attached.','CONDITIONAL_ELECTION')
add('petition',['Doc1','Doc2','Doc3'],4,'Attached is other pertinent documentation (non-originals). List attached documents: [three lines]','List documents actually attached, using only required lines; do not require three attachments or three completed lines.','CONDITIONAL_ATTACHMENT_DETAIL')
add('order',['ArrestOn','ArrestBy'],1,'Arrest records of an arrest occurring on or about ... by the following law enforcement agency','Complete factual description if the arrest-record scope is being requested; order elections remain protected under this packet contract.','CONDITIONAL_SCOPE_DETAIL')
add('order',['ArrestBy1'],1,'Arrest records ... by the following law enforcement agency [continuation line]','Use only if the applicable arresting-agency description needs a second line.','OPTIONAL_CONTINUATION')
add('order',['Agency'],1,'Charging documents created by the following prosecuting agency','Complete when that record scope is requested.','CONDITIONAL_SCOPE_DETAIL')
add('order',['Agency1'],1,'Charging documents created by the following prosecuting agency [continuation line]','Use only if applicable prosecuting-agency description needs a second line.','OPTIONAL_CONTINUATION')
add('order',['CaseNo'],1,'All records relating to the eligible charge(s) in court case number','Complete when that record scope is requested; separate charged-case caption Case remains applicable.','CONDITIONAL_SCOPE_DETAIL')
add('order',['NameArrest'],1,'Name at the time of arrest, if not the same as above','Supply only if the name at arrest differs from the petitioner name; never require a different name to exist.','CONDITIONAL_IDENTITY_DETAIL')
out={'familyId':m['familyId'],'sourceReceipt':str(b/'source-receipt.json'),'fieldMap':str(b/'production-field-map.json'),'instructions':str(b/'participant-instructions.md'),'fieldsWithUnsupportedUnconditionalRequirements':len(rows),'rows':rows,'preserveApplicableRequirements':['Petition Case and CourtCaseNum: charged-case number','Petition EnteredOn: dismissal/not-guilty disposition date','Petition Check Box10 through Check Box13: Section II required Yes/No/N.A. response; source only sends no-charge situation directly to Section III','Petition Check Box14 and Check Box15: prior-history answers','Petition Check Box17: pending charges Yes/No/Unknown; Check Box18 hearing election','Petition Date plus wet signature in p5 declaration','Order Case caption case number'],'noBlanketSuppression':True,'noPdfRepairProposed':True}
(e/'source-conditioned-requirement-defects.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({'fields':len(rows),'petition':sum(r['documentRole']=='petition' for r in rows),'order':sum(r['documentRole']=='order' for r in rows),'evidence':str(e/'source-conditioned-requirement-defects.json')},indent=2))
